use crate::canonical_normalizer::CanonicalEvent;
use crate::sliding_window::SlidingWindowResult;
use crate::tumbling_window::TumblingWindowResult;
use std::collections::{BTreeMap, HashSet};

/// Offline Reference Oracle for Stream Window Correctness Verification
///
/// Implements a brute-force, mathematically exact offline grouping and aggregation model.
/// Compares outputs generated by the high-performance online streaming window state machines
/// against reference partitions to verify event conservation, boundary alignment, and zero-loss guarantees.
pub struct WindowOracle;

impl WindowOracle {
    /// Computes reference offline tumbling window aggregations
    pub fn compute_reference_tumbling_windows(
        events: &[CanonicalEvent],
        window_size_ms: u64,
    ) -> Vec<TumblingWindowResult> {
        let mut buckets: BTreeMap<u64, Vec<String>> = BTreeMap::new();

        for evt in events {
            let t_ms = if evt.event_timestamp_ns > 0 {
                (evt.event_timestamp_ns / 1_000_000) as u64
            } else {
                0
            };
            let win_start = t_ms - (t_ms % window_size_ms);
            buckets
                .entry(win_start)
                .or_default()
                .push(evt.event_id.to_string());
        }

        let mut results = Vec::new();
        for (start_ms, mut ids) in buckets {
            let end_ms = start_ms + window_size_ms;
            ids.sort();
            results.push(TumblingWindowResult {
                window_start_ms: start_ms,
                window_end_ms: end_ms,
                event_count: ids.len(),
                event_ids: ids,
            });
        }

        results
    }

    /// Computes reference offline sliding window aggregations up to max_watermark_ms
    pub fn compute_reference_sliding_windows(
        events: &[CanonicalEvent],
        window_size_ms: u64,
        slide_size_ms: u64,
        max_watermark_ms: u64,
    ) -> Vec<SlidingWindowResult> {
        if events.is_empty() {
            return Vec::new();
        }

        let min_t_ms = events
            .iter()
            .map(|e| (e.event_timestamp_ns.max(0) / 1_000_000) as u64)
            .min()
            .unwrap_or(0);

        let first_win_start = min_t_ms - (min_t_ms % slide_size_ms);
        let mut results = Vec::new();
        let mut win_start = first_win_start;

        while win_start + window_size_ms <= max_watermark_ms {
            let win_end = win_start + window_size_ms;

            // Collect all events with t_ms in [win_start, win_end)
            let mut matching_ids = Vec::new();
            for evt in events {
                let t_ms = (evt.event_timestamp_ns.max(0) / 1_000_000) as u64;
                if t_ms >= win_start && t_ms < win_end {
                    matching_ids.push(evt.event_id.to_string());
                }
            }

            matching_ids.sort();
            results.push(SlidingWindowResult {
                window_start_ms: win_start,
                window_end_ms: win_end,
                event_count: matching_ids.len(),
                event_ids: matching_ids,
            });

            win_start += slide_size_ms;
        }

        results
    }

    /// Verifies online sliding window results against offline oracle reference
    pub fn verify_sliding_windows(
        actual: &[SlidingWindowResult],
        reference: &[SlidingWindowResult],
    ) -> Result<(), String> {
        if actual.len() != reference.len() {
            return Err(format!(
                "Window count mismatch: actual={}, reference={}",
                actual.len(),
                reference.len()
            ));
        }

        for (i, (act, exp)) in actual.iter().zip(reference.iter()).enumerate() {
            if act.window_start_ms != exp.window_start_ms || act.window_end_ms != exp.window_end_ms {
                return Err(format!(
                    "Window {} boundary mismatch: actual [{}, {}), expected [{}, {})",
                    i, act.window_start_ms, act.window_end_ms, exp.window_start_ms, exp.window_end_ms
                ));
            }

            if act.event_count != exp.event_count {
                return Err(format!(
                    "Window {} event count mismatch: actual={}, expected={}",
                    i, act.event_count, exp.event_count
                ));
            }

            let mut act_sorted = act.event_ids.clone();
            act_sorted.sort();
            let mut exp_sorted = exp.event_ids.clone();
            exp_sorted.sort();

            let act_set: HashSet<_> = act_sorted.iter().collect();
            let exp_set: HashSet<_> = exp_sorted.iter().collect();

            if act_set != exp_set {
                return Err(format!(
                    "Window {} event ID set mismatch: actual={:?}, expected={:?}",
                    i, act_set, exp_set
                ));
            }
        }

        Ok(())
    }
}
